/* ===================== BÀI 11 · MOSFET: gate, source, drain, đóng/ngắt và rò ===================== */
/* Bài 11 · MOSFET: gate, source, drain, đóng/ngắt và rò (CM01.04) — sinh bởi tools/author/maytinh/m11.py, không sửa tay.
   Phòng mô phỏng từng bước và bài tập chấm tự động; phần chữ bài học ở lesson.html (nội dung bảo vệ). */
makeMtLab(document.getElementById("lab-l11"),{id:"l11",scenarios:[{"label": "Ví dụ: NMOS từ ngắt tới dẫn", "note": "Tăng điện áp cổng qua ngưỡng 0,4 V (giả định) và quan sát kênh dẫn.", "steps": [{"t": "V_GS = 0: không có kênh, MOSFET ngắt", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"NMOS với cổng 0 V\"><rect x=\"20\" y=\"96\" width=\"320\" height=\"80\" class=\"osoft\" stroke=\"currentColor\"/><text x=\"150\" y=\"168\" class=\"sm\">đế P<\/text><rect x=\"40\" y=\"96\" width=\"80\" height=\"36\" rx=\"6\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"54\" y=\"120\" class=\"sm\">N+ nguồn<\/text><rect x=\"240\" y=\"96\" width=\"80\" height=\"36\" rx=\"6\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"254\" y=\"120\" class=\"sm\">N+ máng<\/text><rect x=\"120\" y=\"86\" width=\"120\" height=\"10\" class=\"muted\" opacity=\".5\"/><text x=\"246\" y=\"92\" class=\"sm\">oxit<\/text><rect x=\"120\" y=\"62\" width=\"120\" height=\"24\" class=\"part\"/><text x=\"160\" y=\"79\" class=\"sm\">cổng<\/text><line x1=\"180\" y1=\"62\" x2=\"180\" y2=\"34\" class=\"wire\"/><text x=\"186\" y=\"30\">G: 0 V<\/text><line x1=\"80\" y1=\"96\" x2=\"80\" y2=\"34\" class=\"wire\"/><text x=\"40\" y=\"30\">S: 0 V<\/text><line x1=\"280\" y1=\"96\" x2=\"280\" y2=\"34\" class=\"wire\"/><text x=\"252\" y=\"22\">D: 1 V<\/text><text x=\"20\" y=\"194\" class=\"sm muted\">Ngắt: không có kênh (chỉ còn dòng rò rất nhỏ)<\/text><\/svg>", "say": "<p>Giữa nguồn N+ và máng N+ là đế P: hai tiếp giáp PN quay lưng vào nhau (Bài 10), nên không có đường cho electron. Giả định V_th = 0,4 V.<\/p>"}, {"t": "V_GS = 0,2 V (dưới ngưỡng): vẫn ngắt", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"NMOS với cổng 0,2 V\"><rect x=\"20\" y=\"96\" width=\"320\" height=\"80\" class=\"osoft\" stroke=\"currentColor\"/><text x=\"150\" y=\"168\" class=\"sm\">đế P<\/text><rect x=\"40\" y=\"96\" width=\"80\" height=\"36\" rx=\"6\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"54\" y=\"120\" class=\"sm\">N+ nguồn<\/text><rect x=\"240\" y=\"96\" width=\"80\" height=\"36\" rx=\"6\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"254\" y=\"120\" class=\"sm\">N+ máng<\/text><rect x=\"120\" y=\"86\" width=\"120\" height=\"10\" class=\"muted\" opacity=\".5\"/><text x=\"246\" y=\"92\" class=\"sm\">oxit<\/text><rect x=\"120\" y=\"62\" width=\"120\" height=\"24\" class=\"part\"/><text x=\"160\" y=\"79\" class=\"sm\">cổng<\/text><line x1=\"180\" y1=\"62\" x2=\"180\" y2=\"34\" class=\"wire\"/><text x=\"186\" y=\"30\">G: 0,2 V<\/text><line x1=\"80\" y1=\"96\" x2=\"80\" y2=\"34\" class=\"wire\"/><text x=\"40\" y=\"30\">S: 0 V<\/text><line x1=\"280\" y1=\"96\" x2=\"280\" y2=\"34\" class=\"wire\"/><text x=\"252\" y=\"22\">D: 1 V<\/text><text x=\"20\" y=\"194\" class=\"sm muted\">Ngắt: không có kênh (chỉ còn dòng rò rất nhỏ)<\/text><\/svg>", "say": "<p>Điện trường của cổng đẩy lỗ trống ra xa bề mặt, nhưng chưa đủ để tạo lớp electron nối hai vùng N+.<\/p>"}, {"t": "V_GS = 1,0 V (trên ngưỡng): có kênh electron", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"NMOS với cổng 1 V, chưa đặt V_DS\"><rect x=\"20\" y=\"96\" width=\"320\" height=\"80\" class=\"osoft\" stroke=\"currentColor\"/><text x=\"150\" y=\"168\" class=\"sm\">đế P<\/text><rect x=\"40\" y=\"96\" width=\"80\" height=\"36\" rx=\"6\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"54\" y=\"120\" class=\"sm\">N+ nguồn<\/text><rect x=\"240\" y=\"96\" width=\"80\" height=\"36\" rx=\"6\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"254\" y=\"120\" class=\"sm\">N+ máng<\/text><rect x=\"120\" y=\"86\" width=\"120\" height=\"10\" class=\"muted\" opacity=\".5\"/><text x=\"246\" y=\"92\" class=\"sm\">oxit<\/text><rect x=\"120\" y=\"62\" width=\"120\" height=\"24\" class=\"part on\"/><text x=\"160\" y=\"79\" class=\"sm\">cổng<\/text><line x1=\"180\" y1=\"62\" x2=\"180\" y2=\"34\" class=\"wire\"/><text x=\"186\" y=\"30\">G: 1 V<\/text><line x1=\"80\" y1=\"96\" x2=\"80\" y2=\"34\" class=\"wire\"/><text x=\"40\" y=\"30\">S: 0 V<\/text><line x1=\"280\" y1=\"96\" x2=\"280\" y2=\"34\" class=\"wire\"/><text x=\"252\" y=\"22\">D: 0 V<\/text><rect x=\"118\" y=\"97\" width=\"124\" height=\"9\" class=\"warm\" opacity=\".85\"/><text x=\"124\" y=\"146\" class=\"sm warm\">kênh dẫn (electron)<\/text><text x=\"20\" y=\"194\" class=\"sm warm\">Dẫn: có kênh nối nguồn – máng<\/text><\/svg>", "ask": {"q": "Cổng NMOS đặt 1,0 V, ngưỡng 0,4 V. Dưới lớp oxit xuất hiện gì?", "o": ["Một lớp lỗ trống", "Một lớp electron nối nguồn và máng (kênh)", "Không có gì thay đổi"], "a": 1}, "say": "<p>Cổng dương hút electron về sát mặt silicon, tạo lớp đảo: một kênh loại N mỏng nằm trong đế P.<\/p>"}, {"t": "Đặt V_DS = 1 V: có dòng từ máng sang nguồn", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"NMOS dẫn có dòng máng\"><rect x=\"20\" y=\"96\" width=\"320\" height=\"80\" class=\"osoft\" stroke=\"currentColor\"/><text x=\"150\" y=\"168\" class=\"sm\">đế P<\/text><rect x=\"40\" y=\"96\" width=\"80\" height=\"36\" rx=\"6\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"54\" y=\"120\" class=\"sm\">N+ nguồn<\/text><rect x=\"240\" y=\"96\" width=\"80\" height=\"36\" rx=\"6\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"254\" y=\"120\" class=\"sm\">N+ máng<\/text><rect x=\"120\" y=\"86\" width=\"120\" height=\"10\" class=\"muted\" opacity=\".5\"/><text x=\"246\" y=\"92\" class=\"sm\">oxit<\/text><rect x=\"120\" y=\"62\" width=\"120\" height=\"24\" class=\"part on\"/><text x=\"160\" y=\"79\" class=\"sm\">cổng<\/text><line x1=\"180\" y1=\"62\" x2=\"180\" y2=\"34\" class=\"wire\"/><text x=\"186\" y=\"30\">G: 1 V<\/text><line x1=\"80\" y1=\"96\" x2=\"80\" y2=\"34\" class=\"wire\"/><text x=\"40\" y=\"30\">S: 0 V<\/text><line x1=\"280\" y1=\"96\" x2=\"280\" y2=\"34\" class=\"wire\"/><text x=\"252\" y=\"22\">D: 1 V<\/text><rect x=\"118\" y=\"97\" width=\"124\" height=\"9\" class=\"warm\" opacity=\".85\"/><text x=\"124\" y=\"146\" class=\"sm warm\">kênh dẫn (electron)<\/text><path d=\"M270 50 H90\" class=\"wire on\"/><path d=\"M96 44 L90 50 L96 44\" class=\"wire on\" fill=\"none\"/><text x=\"20\" y=\"194\" class=\"sm warm\">Dẫn: có kênh nối nguồn – máng, có dòng máng<\/text><\/svg>", "say": "<p>Electron đi từ nguồn sang máng; theo chiều quy ước, dòng đi từ máng về nguồn. Cổng nằm trên lớp oxit cách điện nên gần như không có dòng một chiều chảy vào cổng.<\/p>"}]}, {"label": "Ví dụ: PMOS dẫn khi cổng ở mức thấp", "note": "Mọi thứ đảo dấu so với NMOS.", "steps": [{"t": "PMOS: đế N, nguồn và máng P+", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"PMOS với cổng bằng nguồn\"><rect x=\"20\" y=\"96\" width=\"320\" height=\"80\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"150\" y=\"168\" class=\"sm\">đế N<\/text><rect x=\"40\" y=\"96\" width=\"80\" height=\"36\" rx=\"6\" class=\"osoft\" stroke=\"currentColor\"/><text x=\"54\" y=\"120\" class=\"sm\">P+ nguồn<\/text><rect x=\"240\" y=\"96\" width=\"80\" height=\"36\" rx=\"6\" class=\"osoft\" stroke=\"currentColor\"/><text x=\"254\" y=\"120\" class=\"sm\">P+ máng<\/text><rect x=\"120\" y=\"86\" width=\"120\" height=\"10\" class=\"muted\" opacity=\".5\"/><text x=\"246\" y=\"92\" class=\"sm\">oxit<\/text><rect x=\"120\" y=\"62\" width=\"120\" height=\"24\" class=\"part\"/><text x=\"160\" y=\"79\" class=\"sm\">cổng<\/text><line x1=\"180\" y1=\"62\" x2=\"180\" y2=\"34\" class=\"wire\"/><text x=\"186\" y=\"30\">G: 0 V<\/text><line x1=\"80\" y1=\"96\" x2=\"80\" y2=\"34\" class=\"wire\"/><text x=\"40\" y=\"30\">S: 0 V<\/text><line x1=\"280\" y1=\"96\" x2=\"280\" y2=\"34\" class=\"wire\"/><text x=\"252\" y=\"22\">D: −1 V<\/text><text x=\"20\" y=\"194\" class=\"sm muted\">Ngắt: không có kênh (chỉ còn dòng rò rất nhỏ)<\/text><\/svg>", "say": "<p>Ở PMOS mọi thứ đảo dấu. Ở đây đo điện áp so với nguồn của PMOS (thường nối nguồn cấp V_DD), nên V_GS = 0 nghĩa là cổng ở mức V_DD.<\/p>"}, {"t": "V_GS = −1 V (cổng thấp hơn nguồn): có kênh lỗ trống", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"PMOS với cổng thấp hơn nguồn 1 V\"><rect x=\"20\" y=\"96\" width=\"320\" height=\"80\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"150\" y=\"168\" class=\"sm\">đế N<\/text><rect x=\"40\" y=\"96\" width=\"80\" height=\"36\" rx=\"6\" class=\"osoft\" stroke=\"currentColor\"/><text x=\"54\" y=\"120\" class=\"sm\">P+ nguồn<\/text><rect x=\"240\" y=\"96\" width=\"80\" height=\"36\" rx=\"6\" class=\"osoft\" stroke=\"currentColor\"/><text x=\"254\" y=\"120\" class=\"sm\">P+ máng<\/text><rect x=\"120\" y=\"86\" width=\"120\" height=\"10\" class=\"muted\" opacity=\".5\"/><text x=\"246\" y=\"92\" class=\"sm\">oxit<\/text><rect x=\"120\" y=\"62\" width=\"120\" height=\"24\" class=\"part on\"/><text x=\"160\" y=\"79\" class=\"sm\">cổng<\/text><line x1=\"180\" y1=\"62\" x2=\"180\" y2=\"34\" class=\"wire\"/><text x=\"186\" y=\"30\">G: −1 V<\/text><line x1=\"80\" y1=\"96\" x2=\"80\" y2=\"34\" class=\"wire\"/><text x=\"40\" y=\"30\">S: 0 V<\/text><line x1=\"280\" y1=\"96\" x2=\"280\" y2=\"34\" class=\"wire\"/><text x=\"252\" y=\"22\">D: −1 V<\/text><rect x=\"118\" y=\"97\" width=\"124\" height=\"9\" class=\"warm\" opacity=\".85\"/><text x=\"124\" y=\"146\" class=\"sm warm\">kênh dẫn (lỗ trống)<\/text><path d=\"M90 50 H270\" class=\"wire on\"/><path d=\"M264 44 L270 50 L264 56\" class=\"wire on\"/><text x=\"20\" y=\"194\" class=\"sm warm\">Dẫn: có kênh nối nguồn – máng, có dòng máng<\/text><\/svg>", "ask": {"q": "Nguồn PMOS nối 1 V, cổng nối 0 V (V_GS = −1 V). PMOS thế nào?", "o": ["Dẫn", "Ngắt"], "a": 0}, "say": "<p>Quy tắc nhớ: NMOS dẫn khi cổng ở mức <b>cao<\/b>, PMOS dẫn khi cổng ở mức <b>thấp<\/b>. Ghép một NMOS với một PMOS là CMOS (Bài 12).<\/p>"}]}, {"label": "Ví dụ: Dòng máng theo mô hình bình phương", "note": "Gấp đôi phần điện áp vượt ngưỡng thì dòng gấp 4.", "steps": [{"t": "Giả định: k'·W/L = 2 mA/V², V_th = 0,5 V", "html": "<p class=\"mt-calc\">Vùng bão hòa (V_DS đủ lớn): I_D ≈ ½ · k'(W/L) · (V_GS − V_th)²<\/p>", "say": "<p>Mô hình bình phương cho MOSFET kênh dài; transistor rất nhỏ ngày nay lệch khỏi mô hình này, nhưng nó cho đúng xu hướng.<\/p>"}, {"t": "V_GS = 0,5 V → I_D ≈ 0 mA", "html": "<p class=\"mt-calc\">½ × 2 × (0,5 − 0,5)² = <b>0 mA<\/b><\/p><div class=\"mt-bars\"><div><span>V_GS = 0,5 V<\/span><span><i class=\"\" style=\"width:0.5%\"><\/i><em>0 mA<\/em><\/span><\/div><\/div>"}, {"t": "V_GS = 0,75 V → I_D ≈ 0,0625 mA", "html": "<p class=\"mt-calc\">½ × 2 × (0,75 − 0,5)² = <b>0,0625 mA<\/b><\/p><div class=\"mt-bars\"><div><span>V_GS = 0,5 V<\/span><span><i class=\"\" style=\"width:0.5%\"><\/i><em>0 mA<\/em><\/span><\/div><div><span>V_GS = 0,75 V<\/span><span><i class=\"\" style=\"width:6.2%\"><\/i><em>0,0625 mA<\/em><\/span><\/div><\/div>"}, {"t": "V_GS = 1 V → I_D ≈ 0,25 mA", "html": "<p class=\"mt-calc\">½ × 2 × (1 − 0,5)² = <b>0,25 mA<\/b><\/p><div class=\"mt-bars\"><div><span>V_GS = 0,5 V<\/span><span><i class=\"\" style=\"width:0.5%\"><\/i><em>0 mA<\/em><\/span><\/div><div><span>V_GS = 0,75 V<\/span><span><i class=\"\" style=\"width:6.2%\"><\/i><em>0,0625 mA<\/em><\/span><\/div><div><span>V_GS = 1 V<\/span><span><i class=\"\" style=\"width:25.0%\"><\/i><em>0,25 mA<\/em><\/span><\/div><\/div>"}, {"t": "V_GS = 1,5 V → I_D ≈ 1 mA", "html": "<p class=\"mt-calc\">½ × 2 × (1,5 − 0,5)² = <b>1 mA<\/b><\/p><div class=\"mt-bars\"><div><span>V_GS = 0,5 V<\/span><span><i class=\"\" style=\"width:0.5%\"><\/i><em>0 mA<\/em><\/span><\/div><div><span>V_GS = 0,75 V<\/span><span><i class=\"\" style=\"width:6.2%\"><\/i><em>0,0625 mA<\/em><\/span><\/div><div><span>V_GS = 1 V<\/span><span><i class=\"\" style=\"width:25.0%\"><\/i><em>0,25 mA<\/em><\/span><\/div><div><span>V_GS = 1,5 V<\/span><span><i class=\"w\" style=\"width:100.0%\"><\/i><em>1 mA<\/em><\/span><\/div><\/div>", "ask": {"q": "Overdrive (V_GS − V_th) tăng từ 0,5 V lên 1,0 V (gấp đôi). Dòng máng gấp mấy lần?", "o": ["2 lần", "4 lần", "Không đổi"], "a": 1}, "say": "<p>Dòng tăng theo bình phương phần điện áp vượt ngưỡng. Transistor dẫn mạnh hơn thì nạp xả điện dung nhanh hơn: mạch chạy nhanh hơn khi tăng điện áp (Bài 7, Bài 14).<\/p>"}]}, {"label": "Ví dụ: Cổng không ăn dòng nhưng phải nạp xả", "note": "Điện dung cổng là gốc của công suất động.", "steps": [{"t": "Cổng nằm trên lớp oxit cách điện", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"Cổng cách điện với kênh\"><rect x=\"20\" y=\"96\" width=\"320\" height=\"80\" class=\"osoft\" stroke=\"currentColor\"/><text x=\"150\" y=\"168\" class=\"sm\">đế P<\/text><rect x=\"40\" y=\"96\" width=\"80\" height=\"36\" rx=\"6\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"54\" y=\"120\" class=\"sm\">N+ nguồn<\/text><rect x=\"240\" y=\"96\" width=\"80\" height=\"36\" rx=\"6\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"254\" y=\"120\" class=\"sm\">N+ máng<\/text><rect x=\"120\" y=\"86\" width=\"120\" height=\"10\" class=\"muted\" opacity=\".5\"/><text x=\"246\" y=\"92\" class=\"sm\">oxit<\/text><rect x=\"120\" y=\"62\" width=\"120\" height=\"24\" class=\"part on\"/><text x=\"160\" y=\"79\" class=\"sm\">cổng<\/text><line x1=\"180\" y1=\"62\" x2=\"180\" y2=\"34\" class=\"wire\"/><text x=\"186\" y=\"30\">G: 1 V<\/text><line x1=\"80\" y1=\"96\" x2=\"80\" y2=\"34\" class=\"wire\"/><text x=\"40\" y=\"30\">S: 0 V<\/text><line x1=\"280\" y1=\"96\" x2=\"280\" y2=\"34\" class=\"wire\"/><text x=\"252\" y=\"22\">D: 0 V<\/text><rect x=\"118\" y=\"97\" width=\"124\" height=\"9\" class=\"warm\" opacity=\".85\"/><text x=\"124\" y=\"146\" class=\"sm warm\">kênh dẫn (electron)<\/text><text x=\"20\" y=\"194\" class=\"sm warm\">Dẫn: có kênh nối nguồn – máng<\/text><\/svg>", "say": "<p>Ở trạng thái đứng yên, gần như không có dòng một chiều đi vào cổng (bỏ qua rò qua oxit).<\/p>"}, {"t": "Nhưng cổng là một tụ điện: đổi trạng thái phải nạp hoặc xả", "html": "<p class=\"mt-calc\">Điện tích cần nạp: Q = C · V. Giả định C<sub>cổng<\/sub> = 1 fF, V = 1 V → Q = 10⁻¹⁵ C<\/p>", "ask": {"q": "Cổng không có dòng một chiều. Vậy bật tắt MOSFET hàng tỉ lần mỗi giây có tốn năng lượng không?", "o": ["Không, vì cổng cách điện", "Có, vì mỗi lần phải nạp xả điện dung"], "a": 1}}, {"t": "Nạp xả liên tục là công suất động", "html": "<p class=\"mt-calc\">Năng lượng lấy từ nguồn mỗi chu kỳ nạp–xả: C · V² = 10⁻¹⁵ J; với 10⁹ lần mỗi giây: 10⁻⁶ W = 1 µW cho một cổng<\/p>", "say": "<p>Đó là nguồn gốc công thức P ≈ αCV²f (Bài 14). “Cổng không ăn dòng” chỉ đúng khi tín hiệu đứng yên.<\/p>"}]}, {"label": "Bẫy: Transistor ngắt vẫn rò", "note": "Dòng dưới ngưỡng giảm theo hàm mũ chứ không bằng 0.", "steps": [{"t": "Ngắt không có nghĩa là dòng bằng 0", "html": "<p class=\"mt-calc\">Giả định: tại V_GS = V_th dòng là 1 µA; dưới ngưỡng, mỗi 80 mV giảm thì dòng giảm 10 lần<\/p>", "say": "<p>Dưới ngưỡng, vẫn có một ít electron đủ năng lượng vượt rào thế, nên dòng giảm theo hàm mũ chứ không về 0. Đây là dòng rò dưới ngưỡng. Ở 300 K, độ dốc này không thể tốt hơn khoảng 60 mV cho mỗi lần giảm 10 (≈ 59,5 mV).<\/p>"}, {"t": "V_th = 0,4 V, V_GS = 0: rò 10 pA mỗi transistor", "html": "<p class=\"mt-calc\">0,4 V ÷ 0,08 V = 5 lần giảm 10 → 1 µA × 10⁻⁵ = <b>10 pA<\/b><\/p>"}, {"t": "Một tỉ transistor: 10 mA chỉ để đứng yên", "html": "<p class=\"mt-calc\">10⁹ × 10 pA = 10⁻² A = <b>10 mA<\/b><\/p>", "ask": {"q": "Một chip có 10⁹ transistor, mỗi cái rò 10 pA khi ngắt. Tổng dòng rò bao nhiêu?", "o": ["10 pA", "10 mA", "10 A"], "a": 1}}, {"t": "Hạ V_th xuống 0,3 V: rò gấp khoảng 18 lần", "html": "<p class=\"mt-calc\">0,3 ÷ 0,08 = 3,75 lần giảm 10 → 1 µA × 10⁻³·⁷⁵ ≈ <b>178 pA<\/b>, gấp 17,8 lần<\/p><div class=\"mt-bars\"><div><span>V_th = 0,4 V<\/span><span><i class=\"\" style=\"width:5.6%\"><\/i><em>10 mA<\/em><\/span><\/div><div><span>V_th = 0,3 V<\/span><span><i class=\"e\" style=\"width:100.0%\"><\/i><em>178 mA<\/em><\/span><\/div><\/div>", "say": "<p>Hạ ngưỡng giúp transistor dẫn mạnh hơn ở điện áp thấp (nhanh hơn) nhưng rò nhiều hơn theo hàm mũ. Đây là một lý do điện áp không giảm mãi được (Bài 7). Ngoài ra còn rò qua lớp oxit cổng rất mỏng và rò qua các tiếp giáp PN.<\/p>"}]}, {"label": "Lỗi: Dùng PMOS để kéo xuống đất", "note": "PMOS ngắt khi cổng ở mức cao.", "steps": [{"t": "Muốn nối đầu ra xuống đất khi vào = 1", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>Vào = 1<\/b><small>mức cao<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box warn\"><b>Dùng PMOS?<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Đầu ra<\/b><small>nối xuống GND<\/small><\/div><\/div>", "say": "<p>Người mới hay lắp PMOS vào chỗ cần kéo xuống đất.<\/p>"}, {"t": "PMOS với cổng = 1: ngắt", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"PMOS với cổng ở mức cao: ngắt\"><rect x=\"20\" y=\"96\" width=\"320\" height=\"80\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"150\" y=\"168\" class=\"sm\">đế N<\/text><rect x=\"40\" y=\"96\" width=\"80\" height=\"36\" rx=\"6\" class=\"osoft\" stroke=\"currentColor\"/><text x=\"54\" y=\"120\" class=\"sm\">P+ nguồn<\/text><rect x=\"240\" y=\"96\" width=\"80\" height=\"36\" rx=\"6\" class=\"osoft\" stroke=\"currentColor\"/><text x=\"254\" y=\"120\" class=\"sm\">P+ máng<\/text><rect x=\"120\" y=\"86\" width=\"120\" height=\"10\" class=\"muted\" opacity=\".5\"/><text x=\"246\" y=\"92\" class=\"sm\">oxit<\/text><rect x=\"120\" y=\"62\" width=\"120\" height=\"24\" class=\"part\"/><text x=\"160\" y=\"79\" class=\"sm\">cổng<\/text><line x1=\"180\" y1=\"62\" x2=\"180\" y2=\"34\" class=\"wire\"/><text x=\"186\" y=\"30\">G: 0 V<\/text><line x1=\"80\" y1=\"96\" x2=\"80\" y2=\"34\" class=\"wire\"/><text x=\"40\" y=\"30\">S: 0 V<\/text><line x1=\"280\" y1=\"96\" x2=\"280\" y2=\"34\" class=\"wire\"/><text x=\"252\" y=\"22\">D: −1 V<\/text><text x=\"20\" y=\"194\" class=\"sm muted\">Ngắt: không có kênh (chỉ còn dòng rò rất nhỏ)<\/text><\/svg>", "ask": {"q": "PMOS có nguồn ở V_DD, cổng cũng ở V_DD (mức 1). PMOS thế nào?", "o": ["Dẫn", "Ngắt"], "a": 1}}, {"t": "Sửa: dùng NMOS để kéo xuống đất", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 200\" role=\"img\" aria-label=\"NMOS với cổng mức cao: dẫn\"><rect x=\"20\" y=\"96\" width=\"320\" height=\"80\" class=\"osoft\" stroke=\"currentColor\"/><text x=\"150\" y=\"168\" class=\"sm\">đế P<\/text><rect x=\"40\" y=\"96\" width=\"80\" height=\"36\" rx=\"6\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"54\" y=\"120\" class=\"sm\">N+ nguồn<\/text><rect x=\"240\" y=\"96\" width=\"80\" height=\"36\" rx=\"6\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"254\" y=\"120\" class=\"sm\">N+ máng<\/text><rect x=\"120\" y=\"86\" width=\"120\" height=\"10\" class=\"muted\" opacity=\".5\"/><text x=\"246\" y=\"92\" class=\"sm\">oxit<\/text><rect x=\"120\" y=\"62\" width=\"120\" height=\"24\" class=\"part on\"/><text x=\"160\" y=\"79\" class=\"sm\">cổng<\/text><line x1=\"180\" y1=\"62\" x2=\"180\" y2=\"34\" class=\"wire\"/><text x=\"186\" y=\"30\">G: 1 V<\/text><line x1=\"80\" y1=\"96\" x2=\"80\" y2=\"34\" class=\"wire\"/><text x=\"40\" y=\"30\">S: 0 V<\/text><line x1=\"280\" y1=\"96\" x2=\"280\" y2=\"34\" class=\"wire\"/><text x=\"252\" y=\"22\">D: 1 V<\/text><rect x=\"118\" y=\"97\" width=\"124\" height=\"9\" class=\"warm\" opacity=\".85\"/><text x=\"124\" y=\"146\" class=\"sm warm\">kênh dẫn (electron)<\/text><path d=\"M270 50 H90\" class=\"wire on\"/><path d=\"M96 44 L90 50 L96 44\" class=\"wire on\" fill=\"none\"/><text x=\"20\" y=\"194\" class=\"sm warm\">Dẫn: có kênh nối nguồn – máng, có dòng máng<\/text><\/svg>", "say": "<p>NMOS đặt giữa đầu ra và GND, PMOS đặt giữa V_DD và đầu ra. Ngoài chiều đóng ngắt, NMOS kéo xuống 0 tốt còn PMOS kéo lên V_DD tốt, nên vị trí này cũng cho mức logic sạch nhất.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l11"),"l11",[{"kind": "pick", "t": "Dẫn hay ngắt?", "d": "<p>Giả định |V<sub>th<\/sub>| = 0,4 V. V<sub>GS<\/sub> là điện áp cổng so với nguồn của chính transistor đó.<\/p>", "cats": ["Dẫn", "Ngắt"], "items": [{"q": "NMOS, V<sub>GS<\/sub> = 1,0 V", "a": 0}, {"q": "NMOS, V<sub>GS<\/sub> = 0 V", "a": 1}, {"q": "NMOS, V<sub>GS<\/sub> = 0,2 V", "a": 1}, {"q": "PMOS, V<sub>GS<\/sub> = −1,0 V", "a": 0}, {"q": "PMOS, V<sub>GS<\/sub> = 0 V", "a": 1}, {"q": "PMOS có nguồn ở 1 V, cổng ở 0 V", "a": 0}], "hints": ["NMOS dẫn khi V<sub>GS<\/sub> lớn hơn ngưỡng.", "PMOS dẫn khi V<sub>GS<\/sub> âm hơn −0,4 V.", "Câu cuối: V<sub>GS<\/sub> = 0 − 1 = −1 V."], "why": "NMOS cần V<sub>GS<\/sub> > 0,4 V; PMOS cần V<sub>GS<\/sub> < −0,4 V. PMOS nguồn 1 V, cổng 0 V có V<sub>GS<\/sub> = −1 V nên dẫn."}, {"kind": "num", "t": "Mô hình bình phương", "d": "<p>Dùng I<sub>D<\/sub> = ½·k′(W/L)·(V<sub>GS<\/sub> − V<sub>th<\/sub>)² với k′(W/L) = 2 mA/V², V<sub>th<\/sub> = 0,5 V. Làm tròn 3 chữ số thập phân.<\/p>", "items": [{"q": "V<sub>GS<\/sub> = 0,9 V. I<sub>D<\/sub>?", "a": 0.16000000000000003, "tol": 0.001, "unit": "mA"}, {"q": "V<sub>GS<\/sub> = 1,2 V. I<sub>D<\/sub>?", "a": 0.49, "tol": 0.001, "unit": "mA"}, {"q": "V<sub>GS<\/sub> = 0,4 V. I<sub>D<\/sub> theo mô hình này?", "a": 0, "tol": 0.0005, "unit": "mA"}, {"q": "Phần vượt ngưỡng tăng gấp 3 lần thì I<sub>D<\/sub> gấp mấy lần?", "a": 9}], "hints": ["Tính V<sub>GS<\/sub> − V<sub>th<\/sub> trước.", "0,9 − 0,5 = 0,4; 0,4² = 0,16; ½ × 2 × 0,16.", "Dưới ngưỡng, mô hình bình phương cho 0 (dòng rò dưới ngưỡng không có trong mô hình này)."], "why": "0,9 V: 0,16 mA; 1,2 V: ½ × 2 × 0,49 = 0,49 mA; 0,4 V dưới ngưỡng: 0 theo mô hình; gấp 3 phần vượt ngưỡng thì dòng gấp 3² = 9."}, {"kind": "num", "t": "Dòng rò dưới ngưỡng", "d": "<p>Giả định: tại V<sub>GS<\/sub> = V<sub>th<\/sub> dòng là 1 µA; mỗi S mV giảm thì dòng giảm 10 lần. Tính khi V<sub>GS<\/sub> = 0. Có thể nhập dạng 1e-11.<\/p>", "items": [{"q": "V<sub>th<\/sub> = 0,4 V, S = 80 mV. Dòng một transistor (pA)?", "a": 10, "rel": 0.01, "unit": "pA"}, {"q": "V<sub>th<\/sub> = 0,36 V, S = 60 mV. Dòng một transistor (pA)?", "a": 1, "rel": 0.01, "unit": "pA"}, {"q": "10⁹ transistor, mỗi cái 10 pA. Tổng dòng rò (mA)?", "a": 10, "rel": 0.01, "unit": "mA"}, {"q": "Tổng 10 mA ở nguồn 1,0 V. Công suất rò (mW)?", "a": 10, "rel": 0.01, "unit": "mW"}], "hints": ["Số lần giảm 10 = V<sub>th<\/sub> ÷ S.", "0,4 ÷ 0,08 = 5 → 1 µA × 10⁻⁵ = 10⁻¹¹ A = 10 pA.", "P = V × I."], "why": "0,4/0,08 = 5 → 10 pA; 0,36/0,06 = 6 → 1 pA; 10⁹ × 10⁻¹¹ A = 10⁻² A = 10 mA; 1 V × 10 mA = 10 mW."}]);

makeQuiz("quiz11","score11",[{"q": "NMOS dẫn khi nào?", "o": ["Khi điện áp cổng so với nguồn lớn hơn điện áp ngưỡng", "Khi cổng nối GND", "Khi có dòng lớn chảy vào cổng", "Khi đế nối với máng"], "a": 0, "e": "Cổng dương vượt ngưỡng tạo kênh electron nối nguồn và máng. Cổng cách điện nên không cần dòng một chiều chảy vào cổng."}, {"q": "Vì sao gần như không có dòng một chiều đi vào cổng MOSFET?", "o": ["Vì cổng làm bằng silicon tinh khiết", "Vì cổng nối thẳng với máng", "Vì cổng ngăn với kênh bởi một lớp oxit cách điện", "Vì điện áp cổng luôn bằng 0"], "a": 2, "e": "Lớp oxit là điện môi (Bài 8). Tuy vậy cổng là tụ điện nên mỗi lần đổi trạng thái vẫn phải nạp xả."}, {"q": "Theo mô hình bình phương, phần điện áp vượt ngưỡng tăng gấp đôi thì dòng máng thay đổi thế nào?", "o": ["Gấp đôi", "Không đổi", "Giảm một nửa", "Gấp 4 lần"], "a": 3, "e": "I<sub>D<\/sub> tỉ lệ với (V<sub>GS<\/sub> − V<sub>th<\/sub>)², nên gấp đôi thì gấp 2² = 4."}, {"q": "Độ dốc dưới ngưỡng S = 70 mV. V<sub>GS<\/sub> giảm thêm 140 mV thì dòng rò dưới ngưỡng giảm bao nhiêu lần?", "o": ["2 lần", "100 lần", "140 lần", "10 lần"], "a": 1, "e": "140 ÷ 70 = 2 lần giảm 10, tức giảm 100 lần. Dòng dưới ngưỡng thay đổi theo hàm mũ, không tuyến tính."}, {"q": "Hạ điện áp ngưỡng V<sub>th<\/sub> có tác dụng gì?", "o": ["Transistor dẫn mạnh hơn ở điện áp thấp nhưng rò nhiều hơn", "Giảm cả rò lẫn tốc độ", "Không ảnh hưởng gì", "Làm cổng dẫn điện một chiều"], "a": 0, "e": "V<sub>th<\/sub> thấp → phần vượt ngưỡng lớn hơn → dòng dẫn lớn hơn; nhưng khi ngắt, V<sub>GS<\/sub> = 0 gần ngưỡng hơn nên rò tăng theo hàm mũ."}]);

